/* ══ TECH TOOLS HUB (Jun 2026) ════════════════════════════════════════════
   Each tool is a complete single-file HTML app stored as a string and opened
   in a sandboxed iframe via a Blob URL. Works offline once the PWA is cached,
   zero style/JS clashes with TECH-TICKETS. To add a tool: drop its HTML into
   a const like BLU_FUSION_HTML and push an entry onto TECH_TOOLS. */
var BF_NATIVE={css:"",html:"",js:""};
var CB_NATIVE={css:"",html:"",js:""};
// ST bundle LAZY-LOADED from a sidecar file (Jul 2026): 1.29MB of embedded
// board photos no longer parsed on every app launch (was ~40% of the file).
// Fetched once on first open; the service worker pre-caches st.bundle.json so
// the guide keeps working fully offline after the first load.
var ST_NATIVE=null;
async function _stLoadBundle(){
  if(ST_NATIVE)return ST_NATIVE;
  var r=await fetch("./st.bundle.json");
  if(!r.ok)throw new Error("st.bundle.json HTTP "+r.status);
  ST_NATIVE=await r.json();
  return ST_NATIVE;
}
function _ttDecode(b){return new TextDecoder("utf-8").decode(Uint8Array.from(atob(b),function(c){return c.charCodeAt(0)}))}
// Prepara una herramienta de página completa para el iframe aislado. La guía YE-6
// es una página autónoma y con su propio estilo (tema, fuentes, localStorage), así
// que no hay que reescribir nada — se entrega su HTML completo al iframe tal cual.
function _ttEmbedify(html){return html;}
var YE6_BUNDLE={css:"",html:"",js:""};
var YSG_BUNDLE={css:"",html:"",js:""};
var YE3_BUNDLE={css:"",html:"",js:""};
