// Per-tool native bundle + DOM id prefix. Both tools follow the same pattern:
// fully namespaced CSS (#xxApp), strict-mode IIFE, xx-prefixed ids → safe to
// inject straight into the page (no iframe). Drives the generic _ttMountNative.
var _TT_NATIVE_BUNDLES={
  /* v2.33.1 — El catalogo NO sigue el patron de Blu Fusion, y registrarlo como si
     lo siguiera lo dejaba muerto: (a) su css/html son TEXTO PLANO, no base64 →
     _ttDecode reventaba con "Failed to execute 'atob'"; (b) arranca por boot(),
     no por un IIFE en `js`; (c) no tiene nav/screen/titulo propios; (d) `.pt-top`
     es su BARRA DE BUSQUEDA, no un header de marca — declararlo como `top` la
     escondia; (e) ya esta escrito con los tokens de la app, asi que el puente de
     tema (escrito para el design system de BF) solo le pisaba los chips. */
  parts:{bundle:function(){return PARTS_NATIVE},app:"ptApp",plain:true,bridge:false},
  blufusion:{bundle:function(){return BF_NATIVE},app:"bfApp",nav:"bfNav",screen:"bfScreen",top:".bf-top",title:".bf-screentitle",lang:"bfLang"},
  waterbalance:{bundle:function(){return CB_NATIVE},app:"cbApp",nav:"cbNav",screen:"cbScreen",top:".cb-top",title:".cb-screentitle",lang:"cbLang"},
  smartouch:{bundle:function(){return ST_NATIVE},lazy:function(){return _stLoadBundle()},app:"stApp",nav:"stNav",screen:"stScreen",top:".st-top",title:".st-screentitle",lang:"stLang"},
  ye6pack:{shadow:true,bundle:function(){return YE6_BUNDLE}},
  yseries:{shadow:true,rootClass:"ysg-root",bundle:function(){return YSG_BUNDLE},lang:"ysgLang"},
  ye3pack:{shadow:true,rootClass:"y3-root",bundle:function(){return YE3_BUNDLE}}
};
