async function openTechTool(key){
  // VIEWER: cualquier otra herramienta queda fuera de su alcance
  if(_isViewer()&&key!==VIEWER_TOOL)return;
  var t=null;for(var i=0;i<TECH_TOOLS.length;i++)if(TECH_TOOLS[i].key===key)t=TECH_TOOLS[i];
  if(!t)return;
  try{
    var fr=document.getElementById("ttFrame");
    var host=document.getElementById("ttNativeHost");
    if(t.native){
      // Lazy native bundles (Jul 2026): fetch the sidecar file on first open.
      var _lc=_TT_NATIVE_BUNDLES[t.key];
      if(_lc&&_lc.shadow){
        // Herramientas que son página completa propia (como YE-6): se montan en un
        // shadow root, así su CSS no se fuga a la app ni la app la afecta. Ver
        // _ye6MountShadow — queda nativa (sin iframe), con el tema de la app.
        if(!_ye6MountShadow(t))return;
      }else{
        if(_lc&&_lc.lazy&&!_lc.bundle()){
          try{
            toast("Loading "+t.label.split("\u2014")[0].trim()+"\u2026");
            await _lc.lazy();
          }catch(_le){toast("Could not load tool: "+_le.message,"err");return}
        }
        if(!_ttMountNative(t))return;
      }
      if(fr){fr.style.display="none";fr.src="about:blank"}
      host.style.display="";
    }else{
      // iframe path kept for future tools that aren't vetted for native injection
      var _thKey=key+"|"+((typeof _curTheme==="function")?_curTheme():"light");
      if(!_ttUrls[_thKey]){
        _ttUrls[_thKey]=URL.createObjectURL(new Blob([_ttEmbedify(t.html())],{type:"text/html"}));
      }
      host.style.display="none";
      if(fr){fr.style.display="block";fr.src=_ttUrls[_thKey]}
    }
    document.getElementById("ttHub").style.display="none";
    document.getElementById("ttViewer").style.display="";
    document.getElementById("ttViewerTitle").textContent=t.emoji+" "+t.label;
    // Single shared language control: only for native tools that expose an
    // internal ES/EN toggle; sync the freshly-mounted tool to the saved choice.
    _ttCurKey=(t.native&&_TT_NATIVE_BUNDLES[key]&&_TT_NATIVE_BUNDLES[key].lang)?key:null;
    var _lb=document.getElementById("ttLangBtn");
    if(_lb)_lb.style.display=_ttCurKey?"":"none";
    _ttUpdateLangBtn();
    if(_ttCurKey)_ttSyncToolLang();
    try{window.scrollTo({top:0,behavior:"smooth"})}catch(_e){}
  }catch(e){console.error("[techTools]",e);toast("Could not open tool: "+((e&&e.message)||e),"err")}
}
function closeTechTool(){
  document.getElementById("ttViewer").style.display="none";
  document.getElementById("ttHub").style.display="";
  document.getElementById("ttNativeHost").style.display="none";
  var fr=document.getElementById("ttFrame");if(fr)fr.src="about:blank";
}
